import {
  Group,
  Mesh,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  DirectionalLight,
  PointLight,
  AmbientLight,
  Color,
  SRGBColorSpace,
  DoubleSide,
} from 'three/webgpu';
import {
  uv,
  vec3,
  vec2,
  float,
  mix,
  smoothstep,
  clamp,
  dot,
  texture,
  positionLocal,
  normalLocal,
  uniform,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as PRIM from '@/primitives';

// PLAN
// 1. COMPOSITION: dark gradient backdrop (7x6 @ z=-2.5) frames a 4.0x2.5 tessellated
//    photo plate (parallax-plane, subject left ~x=-1.5) with a bottom scrim + a
//    bottom-left caption stack (kicker/headline/hairline/body) and a small bottom-right
//    caption badge, three depth planes: backdrop < plate < caption/hairline.
// 2. LIGHT RIG: rig-dusk-editorial — key directional #ffc890 @2.8, fill point #b9a68e @3,
//    rim directional #f2f4f6 @1.7, plus a 0.09 ambient floor, all node-local to this group.
// 3. MATERIALS: plate uses MeshStandardNodeMaterial with a TSL color-grade (lifted blacks,
//    shouldered highlights, +12% midtone contrast, -8% desat w/ red channel preserved) and
//    depth-map vertex displacement (0.18u) + edge-rim glow; hairline bar is emissive accent.
// 4. MOTION: plate fades in 0->1 opacity over 500ms (power2.out), caption block rises
//    y+0.4->0 over 700ms (power3.out) starting 120ms later; parallax-scroll primitive
//    (intensity 0.35) drives scroll-bound depth-layer shift.
// 5. FOCAL ELEMENT: the photo plate's rim-lit subject silhouette is the single brightest
//    read; the accent hairline is the only pure-red touch, everything else graded below it.

function hex8ToRGBA(hex8) {
  const h = hex8.replace('#', '');
  const r = parseInt(h.slice(0, 2), 16) / 255;
  const g = parseInt(h.slice(2, 4), 16) / 255;
  const b = parseInt(h.slice(4, 6), 16) / 255;
  const a = h.length >= 8 ? parseInt(h.slice(6, 8), 16) / 255 : 1;
  return { r, g, b, a };
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const colBackground = new Color(colors.background ?? '#0b0b10');
  const colSurface = new Color(colors.surface ?? '#16161d');
  const colPaper = new Color(colors.paper ?? '#e8ecf2');
  const colAccent = new Color(colors.accent ?? '#ff2a38');
  const gradientStops = colors.gradientStops ?? [
    { at: 0.45, hex: '#0b0b1000' },
    { at: 1, hex: '#0b0b10eb' },
  ];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role, fallback) => (items.find((i) => i.role === role)?.text ?? fallback);

  const kickerText = findText('kicker', 'NOVA ATELIER / GENEVA');
  const headlineText = findText('headline', 'Time, Machined.');
  const bodyText = findText('body', 'Every case begins as a single billet of 904L steel.');
  const captionText = findText('caption', 'CALIBRE NA-01 / 72 HOUR RESERVE');

  const root = new Group();
  root.name = 'photo-hero-composite';
  const disposables = { geometries: [], materials: [], textures: [] };
  const timelines = [];
  const primitiveHandles = [];

  // ---- BACKDROP (STAGE) ----
  function buildBackdrop() {
    const geo = new PlaneGeometry(7, 6, 1, 1);
    const mat = new MeshBasicNodeMaterial();
    mat.colorNode = mix(vec3(colSurface.r, colSurface.g, colSurface.b), vec3(colBackground.r, colBackground.g, colBackground.b), uv().y.oneMinus());
    mat.toneMapped = true;
    const mesh = new Mesh(geo, mat);
    mesh.position.set(0, -0.2, -2.5);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    root.add(mesh);
    return mesh;
  }

  // ---- LIGHT RIG (rig-dusk-editorial) ----
  function buildLights(target) {
    const ambient = new AmbientLight(0xffffff, 0.09);
    const key = new DirectionalLight(0xffc890, 2.8);
    key.position.set(target.x + 3, target.y + 0.9, target.z + 1.2);
    key.target.position.set(target.x, target.y + 0.4, target.z);
    const fill = new PointLight(0xb9a68e, 3, 9, 2);
    fill.position.set(target.x - 2.4, target.y + 0.6, target.z + 1.8);
    const rim = new DirectionalLight(0xf2f4f6, 1.7);
    rim.position.set(target.x - 1.8, target.y + 2.8, target.z - 2);
    rim.target.position.set(target.x, target.y + 0.6, target.z);
    root.add(ambient, key, key.target, fill, rim, rim.target);
    return [ambient, key, fill, rim];
  }

  // ---- PHOTO PLATE (parallax-plane, tessellated, depth-displaced, filmic grade) ----
  function buildPlate() {
    const width = 4.0;
    const height = 2.5;
    const segs = 64;
    const geo = new PlaneGeometry(width, height, segs, segs);
    const mat = new MeshStandardNodeMaterial({
      color: new Color(colors.surface ?? '#16161d'),
      roughness: 0.62,
      metalness: 0.08,
    });
    mat.transparent = true;
    mat.opacityNode = uniform(0);
    mat.side = DoubleSide;

    const plate = new Mesh(geo, mat);
    plate.position.set(-1.5, -0.1, 0);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    root.add(plate);

    const imageUrl = config.imageUrl;
    const depthUrl = config.depthMapUrl;
    const amplitude = 0.18;

    Promise.all([
      imageUrl ? ctx.textureLoader.loadTexture(imageUrl) : Promise.resolve(null),
      depthUrl ? ctx.textureLoader.loadTexture(depthUrl) : Promise.resolve(null),
    ]).then(([colorTex, depthTex]) => {
      if (colorTex) {
        colorTex.colorSpace = SRGBColorSpace;
        disposables.textures.push(colorTex);
      }
      if (depthTex) {
        disposables.textures.push(depthTex);
      }

      const uvNode = uv();
      let colorNode;
      if (colorTex) {
        const rawColor = texture(colorTex, uvNode).rgb;
        const lift = vec3(0.051, 0.051, 0.070);
        let graded = mix(lift, rawColor, 0.92);
        const luma = dot(graded, vec3(0.299, 0.587, 0.114));
        const shoulder = mix(graded, vec3(colPaper.r, colPaper.g, colPaper.b), smoothstep(0.7, 1.0, luma).mul(0.15));
        graded = shoulder;
        graded = graded.sub(0.5).mul(1.12).add(0.5);
        const gray = dot(graded, vec3(0.299, 0.587, 0.114));
        const desatAmt = 0.08;
        const gCh = mix(gray, graded.g, 1.0 - desatAmt);
        const bCh = mix(gray, graded.b, 1.0 - desatAmt);
        colorNode = vec3(graded.r, gCh, bCh);

        if (depthTex) {
          const texel = 1.0 / 512.0;
          const dC = texture(depthTex, uvNode).r;
          const dX1 = texture(depthTex, uvNode.add(vec2(texel, 0.0))).r;
          const dX0 = texture(depthTex, uvNode.sub(vec2(texel, 0.0))).r;
          const dY1 = texture(depthTex, uvNode.add(vec2(0.0, texel))).r;
          const dY0 = texture(depthTex, uvNode.sub(vec2(0.0, texel))).r;
          const edge = clamp(dX1.sub(dX0).abs().add(dY1.sub(dY0).abs()).mul(6.0), 0.0, 1.0);
          const rimGlow = vec3(1.0, 0.784, 0.565).mul(edge).mul(0.35);
          colorNode = colorNode.add(rimGlow);
          const dispVal = dC.sub(0.5).mul(amplitude);
          mat.positionNode = positionLocal.add(normalLocal.mul(dispVal));
        }
      } else {
        colorNode = vec3(colSurface.r, colSurface.g, colSurface.b);
      }
      mat.colorNode = colorNode;
      mat.needsUpdate = true;
    }).catch(() => {});

    return plate;
  }

  // ---- BOTTOM SCRIM (color.gradient) ----
  function buildScrim(plate) {
    const stopA = hex8ToRGBA(gradientStops[0]?.hex ?? '#0b0b1000');
    const stopB = hex8ToRGBA(gradientStops[1]?.hex ?? '#0b0b10eb');
    const atA = gradientStops[0]?.at ?? 0.45;
    const atB = gradientStops[1]?.at ?? 1.0;

    const geo = new PlaneGeometry(4.0, 1.4, 1, 1);
    const mat = new MeshBasicNodeMaterial();
    mat.transparent = true;
    const t = uv().y.oneMinus(); // 0 top -> 1 bottom
    const alpha = smoothstep(atA, atB, t).mul(stopB.a);
    const colorNode = mix(vec3(stopA.r, stopA.g, stopA.b), vec3(stopB.r, stopB.g, stopB.b), t);
    mat.colorNode = colorNode;
    mat.opacityNode = alpha;
    const mesh = new Mesh(geo, mat);
    mesh.position.set(plate.position.x, plate.position.y - 0.55, plate.position.z + 0.02);
    disposables.geometries.push(geo);
    disposables.materials.push(mat);
    root.add(mesh);
    return mesh;
  }

  // ---- CAPTION BLOCK (bottom-left, kicker/headline/hairline/body + caption badge) ----
  function buildCaptionBlock(plate) {
    const group = new Group();
    group.position.set(plate.position.x - 1.5, plate.position.y - 0.75, plate.position.z + 0.05);
    root.add(group);

    const kicker = ctx.fontAtlas.createText(kickerText, {
      fontSize: 9,
      color: colPaper.getHexString ? `#${colPaper.getHexString()}` : '#e8ecf2',
      align: 'left',
      letterSpacingPx: 9 * 0.12,
    });
    kicker.position.set(0, 0.85, 0);
    group.add(kicker);

    const headline = ctx.fontAtlas.createText(headlineText, {
      fontSize: 34,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 34 * -0.01,
    });
    headline.position.set(0, 0.55, 0);
    group.add(headline);

    const hairlineGeo = new PlaneGeometry(0.75, 0.02, 1, 1);
    const hairlineMat = new MeshStandardNodeMaterial({
      color: colAccent,
      roughness: 1,
      metalness: 0,
    });
    hairlineMat.emissiveNode = vec3(colAccent.r, colAccent.g, colAccent.b).mul(1.8);
    const hairline = new Mesh(hairlineGeo, hairlineMat);
    hairline.position.set(0.375, 0.30, 0.01);
    disposables.geometries.push(hairlineGeo);
    disposables.materials.push(hairlineMat);
    group.add(hairline);

    const body = ctx.fontAtlas.createText(bodyText, {
      fontSize: 13,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 320,
    });
    body.position.set(0, 0.12, 0);
    group.add(body);

    const badge = ctx.fontAtlas.createText(captionText, {
      fontSize: 9,
      color: '#e8ecf2',
      align: 'right',
      letterSpacingPx: 9 * 0.12,
    });
    badge.position.set(plate.position.x + 1.3 - group.position.x, plate.position.y - 1.0 - group.position.y, 0.05);
    group.add(badge);

    return group;
  }

  // ---- assemble ----
  buildBackdrop();
  const plate = buildPlate();
  buildLights(plate.position);
  buildScrim(plate);
  const captionGroup = buildCaptionBlock(plate);

  // ---- primitive: parallax-scroll ----
  const parallaxCfg = (config.cinematicPrimitives ?? []).find((p) => p.name === 'parallax-scroll');
  const parallaxIntensity = parallaxCfg?.params?.intensity ?? 0.35;
  const parallaxResult = PRIM.default?.['parallax-scroll']
    ? null
    : null;
  try {
    const handle = ctx.primitives['parallax-scroll'](plate, { intensity: parallaxIntensity });
    if (handle) primitiveHandles.push(handle);
  } catch (e) {
    // primitive unavailable — non-fatal
  }

  // ---- motion: plate mount fade-in + caption rise-in ----
  captionGroup.position.y -= 0.4;
  const tl = gsap.timeline();
  timelines.push(tl);
  tl.to(plate.material.opacityNode, {
    value: 1,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  tl.to(captionGroup.position, {
    y: captionGroup.position.y + 0.4,
    duration: 0.7,
    ease: 'power3.out',
  }, 0.12);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const t of timelines) {
      t.kill();
    }
    for (const h of primitiveHandles) {
      h?.cleanup?.();
    }
    for (const g of disposables.geometries) {
      g.dispose();
    }
    for (const m of disposables.materials) {
      m.dispose();
    }
    for (const tex of disposables.textures) {
      tex.dispose();
    }
    root.traverse((obj) => {
      if (obj.userData?.dispose) obj.userData.dispose();
    });
  };

  return root;
}

